function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least 1 node.';
  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Every node value is between 1 and 10^5.';
  if (new Set(values).size !== values.length) return 'All node values must be different.';
  return null;
}

