  // Collect each level depth-first, then use "length minus number of cycles" of the sorting permutation.
  const levels = [];
  const visit = (node, depth) => {
    if (!node) return;
    (levels[depth] = levels[depth] || []).push(node.val);
    visit(node.left, depth + 1);
    visit(node.right, depth + 1);
  };
  visit(root, 0);
  let total = 0;
  for (const level of levels) {
    const order = level.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]).map(p => p[1]);
    const seen = new Array(level.length).fill(false);
    let cycles = 0;
    for (let s = 0; s < level.length; s++) {
      if (seen[s]) continue;
      cycles++;
      for (let k = s; !seen[k]; k = order[k]) seen[k] = true;
    }
    total += level.length - cycles;
  }
  return total;
}

