function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 90) : 1 + Math.floor(rand() * 12);
  // Build a random shape: a downward chain first (sometimes long), then attach nodes to random free slots.
  const chain = large ? (rand() < 0.3 ? 50 + Math.floor(rand() * 200) : 1) : (rand() < 0.2 ? n : 1);
  const nodes = [{ left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with a marker for each node, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    out.push(0);
    queue.push(nodes[queue[q]].left, nodes[queue[q]].right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  // Distinct values, either fully random or sorted in level order with a few swaps.
  const limit = large ? 100000 : (rand() < 0.3 ? 100000 : 30);
  const pool = new Set();
  while (pool.size < n) pool.add(limit === 100000 && !large && rand() < 0.5 ? 100000 - Math.floor(rand() * 20) : 1 + Math.floor(rand() * limit));
  const values = [...pool];
  if (rand() < 0.35) {
    values.sort((a, b) => a - b);
    const swaps = Math.floor(rand() * (large ? 40 : 3));
    for (let s = 0; s < swaps; s++) {
      const a = Math.floor(rand() * n), b = Math.floor(rand() * n);
      [values[a], values[b]] = [values[b], values[a]];
    }
  }
  let next = 0;
  return [out.map(v => v === null ? null : values[next++])];
}
